import { describe, it, expect } from "vitest";

import * as utf_32le from "./utf-32le.js";

describe("UTF-32 (little-endian)", () => {
  describe("encode", () => {
    it("correctly encodes sample inputs", () => {
      // python3 -c 'print("يولد جميع البشر أحرارًا ومتساوون في الكرامة والحقوق، وقد وهبوا عقلاً وضميرًا وعليهم أن يعاملوا بعضهم بعض بروح الإخاء." .encode("utf-32le").hex())'
      expect(
        utf_32le.encode(
          "يولد جميع البشر أحرارًا ومتساوون في الكرامة والحقوق، وقد وهبوا عقلاً وضميرًا وعليهم أن يعاملوا بعضهم بعض بروح الإخاء.",
        ),
      ).toEqual(
        Uint8Array.fromHex(
          "",
        ),
      );
    });
  });

  describe("survives roundtrip conversion", () => {
    it("sample input", () => {
      const input =
        "يولد جميع البشر أحرارًا ومتساوون في الكرامة والحقوق، وقد وهبوا عقلاً وضميرًا وعليهم أن يعاملوا بعضهم بعض بروح الإخاء.";

      expect(utf_32le.decode(utf_32le.encode(input))).toEqual(input);
      expect(
        utf_32le.decode(utf_32le.encode(input, { addBOM: true }), {
          stripBOM: true,
        }),
      ).toEqual(input);
    });
  });
});
